// hourly builds an Open-Meteo response for 2026-05-01 with the activity
// hours 08:00–10:00 UTC; all other hours carry extreme values that must not
// be used.
func hourly() string {
	var times, temp, app, prec, code, wind, dir, gust []string
	for h := range 24 {
		times = append(times, fmt.Sprintf(`"2026-05-01T%02d:00"`, h))
		in := h >= 8 && h <= 10
		pick := func(v, other string) string {
			if in {
				return v
			}
			return other
		}
		temp = append(temp, pick(fmt.Sprint(10+h), "40"))
		app = append(app, pick(fmt.Sprint(8+h), "40"))
		prec = append(prec, pick("0.2", "9"))
		code = append(code, pick(map[int]string{8: "1", 9: "61", 10: "3"}[h], "95"))
		wind = append(wind, pick("10", "99"))
		dir = append(dir, pick(map[int]string{8: "350", 9: "10", 10: "0"}[h], "180"))
		gust = append(gust, pick(fmt.Sprint(20+h), "120"))
	}
	j := func(s []string) string { return "[" + strings.Join(s, ",") + "]" }
	return `{"hourly":{"time":` + j(times) + `,"temperature_2m":` + j(temp) + `,"apparent_temperature":` + j(app) +
		`,"precipitation":` + j(prec) + `,"weather_code":` + j(code) + `,"wind_speed_10m":` + j(wind) +
		`,"wind_direction_10m":` + j(dir) + `,"wind_gusts_10m":` + j(gust) + `}}`
}

func TestFetchSummarizesActivityHours(t *testing.T) {
	var gotPath, gotQuery string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotPath, gotQuery = r.URL.Path, r.URL.RawQuery
		fmt.Fprint(w, hourly())
	}))
	defer srv.Close()
	c := &Client{HTTP: srv.Client(), ArchiveURL: srv.URL + "/archive", ForecastURL: srv.URL + "/forecast",
		Now: func() time.Time { return time.Date(2026, 10, 26, 0, 0, 0, 0, time.UTC) }}

	w, err := c.Fetch(context.Background(), 48.123456, 12.876543, time.Date(2026, 5, 1, 8, 30, 0, 0, time.UTC), 2*time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	if gotPath != "/archive" || !strings.Contains(gotQuery, "latitude=48.12") || !strings.Contains(gotQuery, "longitude=12.88") ||
		!strings.Contains(gotQuery, "start_date=2026-05-01") {
		t.Errorf("request %s?%s", gotPath, gotQuery)
	}
	want := store.Weather{Status: store.WeatherOK, TempMinC: 18, TempMaxC: 20, ApparentC: 16, WindKmh: 10, WindDirDeg: 0,
		GustKmh: 30, PrecipMM: 0.6, Code: 61}
	if w != want {
		t.Errorf("weather %+v\nwant    %+v", w, want)
	}

	// Recent activities use the forecast API.
	c.Now = func() time.Time { return time.Date(2026, 5, 10, 0, 0, 0, 0, time.UTC) }
	if _, err := c.Fetch(context.Background(), 48, 12, time.Date(2026, 5, 1, 8, 0, 0, 0, time.UTC), time.Hour); err != nil || gotPath != "/forecast" {
		t.Errorf("recent: %s %v", gotPath, err)
	}
}

func TestFetchErrors(t *testing.T) {
	status := http.StatusBadRequest
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(status)
		fmt.Fprint(w, `{"error":true,"reason":"out of range"}`)
	}))
	defer srv.Close()
	c := &Client{HTTP: srv.Client(), ArchiveURL: srv.URL, ForecastURL: srv.URL, Now: time.Now}
	start := time.Date(2020, 1, 1, 8, 0, 0, 0, time.UTC)
	if _, err := c.Fetch(context.Background(), 48, 12, start, time.Hour); err == nil || !strings.Contains(err.Error(), "out of range") {
		t.Errorf("400: %v", err)
	}
	status = http.StatusTooManyRequests
	if _, err := c.Fetch(context.Background(), 48, 12, start, time.Hour); err != ErrRateLimited {
		t.Errorf("429: %v", err)
	}
}

func TestBackfillStoresWeatherAndErrors(t *testing.T) {
	ctx := context.Background()
	st, err := store.OpenMemory(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer st.Close()
	im := &importer.Importer{Store: st}
	o := fittest.Default() // 2026-05-01 08:01 UTC with GPS
	ride := im.ImportReader(ctx, bytes.NewReader(fittest.Encode(t, o)), "a")
	o.Serial, o.WithGPS = 7, false
	indoor := im.ImportReader(ctx, bytes.NewReader(fittest.Encode(t, o)), "b")

	var calls atomic.Int32
	var fail atomic.Bool
	fail.Store(true)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		if fail.Load() {
			http.Error(w, `{"error":true,"reason":"boom"}`, http.StatusInternalServerError)
			return
		}
		fmt.Fprint(w, hourly())
	}))
	defer srv.Close()
	svc := &Service{Store: st, Batch: 10, RetryAfter: -time.Hour, // retry immediately in the test
		Client: &Client{HTTP: srv.Client(), ArchiveURL: srv.URL, ForecastURL: srv.URL, Now: time.Now}}

	if n, err := svc.Backfill(ctx); n != 0 || err != nil || calls.Load() != 1 {
		t.Fatalf("failing run: %d %v calls %d", n, err, calls.Load())
	}
	if _, ok, _ := st.Weather(ctx, ride.ActivityID); ok {
		t.Fatal("error stored as weather")
	}
	fail.Store(false)
	if n, err := svc.Backfill(ctx); n != 1 || err != nil {
		t.Fatalf("retry: %d %v", n, err)
	}
	w, ok, _ := st.Weather(ctx, ride.ActivityID)
	if !ok || w.TempMaxC != 18 {
		t.Errorf("stored %+v %v", w, ok)
	}
	if _, ok, _ := st.Weather(ctx, indoor.ActivityID); ok || calls.Load() != 2 {
		t.Errorf("indoor activity must not be looked up (calls %d)", calls.Load())
	}
}
